#include "adventure.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static Adventure a;
static void Press(unsigned button){GameInput in={0};in.touchMove=-1;in.pressed=(uint16_t)button;in.held=(uint16_t)button;Adventure_Input(&a,in,0,0,0,0);}
static void Dialogue(void){unsigned guard=0;while(a.mode==ADV_DIALOGUE){assert(guard++<10);Press(GAME_A);}}
static void BattleReady(void){GameInput none={0};none.touchMove=-1;for(unsigned i=0;i<61;i++)Adventure_Tick(&a,none);assert(a.mode==ADV_BATTLE);}
static void Saved(void){uint8_t bytes[ADVENTURE_SAVE_BYTES];size_t n;AdventureSave copy={0};assert(Adventure_SaveValid(&a.save));assert(Adventure_SaveEncode(&a.save,bytes,sizeof(bytes),&n));assert(n<sizeof(bytes));assert(Adventure_SaveDecode(&copy,bytes,n));assert(!memcmp(&copy.appearance,&a.save.appearance,sizeof(copy.appearance)));assert(copy.step==a.save.step&&copy.partyCount==a.save.partyCount&&copy.boxCount==a.save.boxCount);bytes[20]^=1;assert(!Adventure_SaveDecode(&copy,bytes,n));bytes[20]^=1;assert(!Adventure_SaveDecode(&copy,bytes,n-1));assert(!Adventure_SaveEncode(&a.save,bytes,32,&n));}
static void Routes(void){for(unsigned m=0;m<ADVENTURE_MAPS;m++){unsigned queue[768],head=0,tail=0;unsigned char visited[768]={0};const AdventureMap *map=&gAdventureMaps[m];unsigned start=16*32+16;assert(!map->blocked[start]);queue[tail++]=start;visited[start]=1;while(head<tail){unsigned t=queue[head++];int x=t%32,y=t/32;int dx[4]={-1,1,0,0},dy[4]={0,0,-1,1};for(unsigned d=0;d<4;d++){int nx=x+dx[d],ny=y+dy[d];if(nx<0||nx>=32||ny<0||ny>=24)continue;unsigned n=ny*32+nx;if(!visited[n]&&!map->blocked[n]){visited[n]=1;queue[tail++]=n;}}}assert(visited[9*32+16]);static const unsigned exits[4]={1*32+16,12*32+30,22*32+16,12*32+1};for(unsigned j=0;j<map->linkCount;j++){assert(map->links[j]<ADVENTURE_MAPS);assert(visited[exits[j]]);}unsigned grass=0;for(unsigned j=0;j<768;j++)if(map->grass[j]&&visited[j])grass++;assert(grass);}}
static void SaveFiles(void){char path[128],backup[132];snprintf(path,sizeof(path),"/tmp/platinum-adventure-save-%ld",(long)getpid());snprintf(backup,sizeof(backup),"%s.bak",path);AdventureSave copy;assert(Adventure_SaveWrite(path,&a.save));a.save.money=1234;assert(Adventure_SaveWrite(path,&a.save));assert(Adventure_SaveRead(path,&copy)==1&&copy.money==1234);FILE *f=fopen(path,"wb");assert(f);fwrite("damaged",1,7,f);fclose(f);assert(Adventure_SaveRead(path,&copy)==2&&copy.money!=1234);assert(Adventure_SaveWrite(path,&a.save));assert(Adventure_SaveRead(path,&copy)==1&&copy.money==1234);remove(path);remove(backup);}
static void FullCampaign(void){unsigned battles=0,doubles=0;Adventure_Init(&a);Adventure_New(&a);assert(a.mode==ADV_CREATOR);a.cursor=4;unsigned old=a.save.appearance.option[3];Press(GAME_RIGHT);assert(a.save.appearance.option[3]!=old);GameInput none={0};none.touchMove=-1;Adventure_Input(&a,none,1,0,0,0);Dialogue();assert(a.mode==ADV_FIELD);Saved();assert(!Adventure_Travel(&a,33,0));for(unsigned step=0;step<ADVENTURE_EVENTS;step++){assert(a.save.step==step);const AdventureEvent *e=&gAdventureEvents[step];assert(Adventure_Travel(&a,e->map,0));a.save.x=256*256;a.save.y=180*256;Adventure_Interact(&a);assert(a.mode==ADV_DIALOGUE);Dialogue();if(e->kind==1){assert(a.mode==ADV_STARTER);a.cursor=0;Press(GAME_A);Dialogue();assert(a.save.party[0].dex==387&&a.save.party[0].level==5);}else if(e->kind>=2&&e->kind<=5){BattleReady();battles++;if(e->doubles){assert(a.battle.doubles);doubles++;}if(e->kind==5){a.battle.combat.fighters[1].hp=1;a.battle.combat.fighters[1].status=COMBAT_STATUS_PARALYSIS;a.save.balls=999;for(unsigned tries=0;tries<100&&!a.caughtBattle;tries++)Adventure_Catch(&a);assert(a.caughtBattle&&a.save.partyCount==2);}else a.battle.winner=1;Adventure_FinishBattle(&a,0);Dialogue();}assert(a.save.step==step+1);assert(a.save.partyCount<3);Saved();}assert(a.save.badges==255&&a.save.champion&&a.save.step==41);assert(a.save.party[0].dex==389);assert(battles>=25&&doubles==4);SaveFiles();printf("Scripted campaign-state progression:41 events,%u constructed battles,%u actual2v2 setups; outcomes injected, not a gameplay playthrough.\n",battles,doubles);}
static void FieldAndRoster(void){Adventure_Init(&a);Adventure_New(&a);a.mode=ADV_FIELD;int32_t x=a.save.x;GameInput in={0};in.touchMove=-1;in.held=GAME_RIGHT;for(unsigned i=0;i<10;i++)Adventure_Tick(&a,in);assert(a.save.x>x&&a.facing==2);assert(a.followerX!=a.save.x);assert(Adventure_SaveValid(&a.save));a.save.appearance.option[3]=255;assert(!Adventure_SaveValid(&a.save));assert(gSpeciesCount==493);for(unsigned dex=1;dex<=493;dex++){const ArenaSpecies *s=ArenaSpecies_Find(dex);AdventureMon m;assert(s&&s->animation[1].count&&s->animation[2].count);Adventure_MakeMon(&m,dex,50);CombatFighterConfig c=Adventure_Config(&m);assert(c.hp&&c.attack&&c.defense&&c.spAttack&&m.moves[0]);assert(c.species==dex);}Adventure_MakeMon(&a.save.party[0],387,5);assert(a.save.party[0].hp==22);Adventure_StartLab(&a,1);assert(a.battle.combat.fighterCount==4);assert(a.battle.partyCount[0]==4);}
static void SixPartyAndDefeat(void){Adventure_Init(&a);Adventure_New(&a);a.save.partyCount=6;a.save.step=11;a.save.map=7;a.mode=ADV_FIELD;for(unsigned i=0;i<6;i++)Adventure_MakeMon(&a.save.party[i],i+1,14);a.save.x=256*256;a.save.y=180*256;Adventure_Interact(&a);Dialogue();BattleReady();assert(a.battle.partyCount[0]==6&&a.battle.partyCount[1]==3);for(unsigned i=0;i<6;i++){assert(Game_Switch(&a.battle,0));assert(a.battle.combat.fighters[0].hp);}a.battle.winner=2;Adventure_FinishBattle(&a,0);Dialogue();assert(a.save.step==11&&Adventure_Healthy(&a)==6);a.mode=ADV_FIELD;Adventure_Interact(&a);Dialogue();BattleReady();assert(a.battle.partyCount[1]==3);Adventure_FinishBattle(&a,1);assert(a.save.step==11);}
int main(void){Routes();FieldAndRoster();SixPartyAndDefeat();FullCampaign();puts("Adventure: roster, editable profile, movement/trail, route reachability, six-slot switching, defeat/retry/retreat, catching, level evolution, story flags, CRC save and backup recovery passed.");return 0;}
